import {
  PlaneGeometry,
  Mesh,
  MeshBasicNodeMaterial,
  TextureLoader,
  Vector3,
  Euler,
} from 'three/webgpu';
import { texture } from 'three/tsl';

/**
 * Creates a static pricing card plane with an image.
 * @param {import('@/primitives').NodeConfig} config
 * @param {import('@/primitives').NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createPricingCard3(config, ctx) {
  // --- Geometry & Material ---
  const geometry = new PlaneGeometry(1, 1); // scaled via config
  const texLoader = ctx.textureLoader;
  const tex = texLoader.load(config.imageUrl);
  const material = new MeshBasicNodeMaterial({
    map: tex,
    transparent: false,
    side: 2, // DoubleSide
  });

  const mesh = new Mesh(geometry, material);
  mesh.position.copy(
    new Vector3(
      config.scenePosition.x,
      config.scenePosition.y,
      config.scenePosition.z
    )
  );
  mesh.rotation.copy(
    new Euler(
      config.scenePosition.rotation?.x ?? 0,
      config.scenePosition.rotation?.y ?? 0,
      config.scenePosition.rotation?.z ?? 0
    )
  );
  mesh.scale.copy(
    new Vector3(
      config.scenePosition.scale?.x ?? 1,
      config.scenePosition.scale?.y ?? 1,
      config.scenePosition.scale?.z ?? 1
    )
  );

  // --- Atlas region (unused for plane but available) ---
  // config.atlasRegion provided, but plane texture is separate image.

  // --- No handlers, no cinematicPrimitives, no data bindings ---

  // --- Cleanup ---
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    tex.dispose();
  };

  return mesh;
}
